// Subject identity review lists and operator approval dialogs.
const identityDecisions={};
let identityAudit=null;
const identityKinds = {personal:'个人',enterprise:'企业',agent:'经办人'};
const identityTypes = ['注册','更新','续期','解冻','注销'];
const identityTypesFor=kind=>kind==='agent'?['注册','更新','注销']:identityTypes;
const identityTypeCode=type=>({注册:'register',更新:'update',续期:'renew',解冻:'unfreeze',注销:'cancel'}[type]);
const identitySchemas = {
 personal:{fields:[['name','姓名'],['code','证件号码'],['phone','手机号'],['auth','认证方式',['第三方服务入口','身份证或社保卡实名核验']]],columns:[['name','姓名'],['code','证件号码'],['phone','手机号'],['document','证件类型'],['auth','认证方式'],['type','审核类型'],['submitter','提交人'],['submitted','提交时间']]},
 enterprise:{fields:[['name','企业名称'],['code','统一社会信用代码'],['organizationType','企业类型',['企事业单位法人','机关法人','非法人组织','其它']],['legal','法人名称'],['phone','法人手机号'],['legalCode','法人证件号']],columns:[['name','企业名称'],['code','统一社会信用代码'],['organizationType','企业类型'],['legal','法定代表人'],['phone','法人手机号'],['legalCode','法人证件号'],['type','审核类型'],['submitter','提交人'],['submitted','提交时间']]},
 agent:{fields:[['name','经办人姓名'],['code','经办人标识'],['organization','所属组织名称'],['organizationCode','所属组织标识']],columns:[['name','经办人姓名'],['code','经办人标识'],['organization','所属组织名称'],['organizationCode','所属组织标识'],['type','审核类型'],['submitter','提交人'],['submitted','提交时间']]}
};
const identityExamples = {
 personal:['李十一','李九','Tingting','Zhangzhou','数据提供者4','zhaohk','zzzzzzz'].map((name,i)=>({name,code:['500228199504184170','500228199511200837','500106199902022319','500102199907100230','410120194510144514','111111111111111178','372928176802123456'][i],phone:['18700010011','18700010009','17356130980','17308395051','18765803199','17308395610','17867209387'][i],document:'中华人民共和国居民身份证',auth:i===4||i===6?'身份证或社保卡实名核验':'第三方服务入口',type:['注册','更新','解冻','注销'][i%4],submitter:i<2?name:'xuxiaolong',submitted:['2026-10-29 17:18:07','2026-10-29 17:04:42','2026-09-16 09:43:24','2026-09-16 09:40:51','2026-09-15 17:47:26','2026-09-15 10:27:16','2026-09-15 09:38:29'][i]})),
 enterprise:['产品测试1103','李十的世界和平公司','渝时公司','csqy1028001','csqy1027001','杭州趣链科技股份有限公司','重庆数字资源集团有限公司','测试企业使用使用','测试企业1351'].map((name,i)=>({name,code:['911201132985503116','91500100HE16LJEKWA','915001093316437724','91310115MA1H81029P','91310115MA1H71027P','92410185E4J2QX50PK','91460300B8TWQTXPW6','91310115MA1H91517P','91310115MA1H91351P'][i],organizationType:['其它','非法人组织','企事业单位法人','机关法人','企事业单位法人','机关法人','企事业单位法人','企事业单位法人','机关法人'][i],legal:['不知道','李十','渝时','11','11','杨世龙','廖国元','11','11'][i],phone:i<3?['18777777777','18700010010','15223670619'][i]:i===5?'18333333333':i===6?'18711111111':'',legalCode:'500103199908191234',type:[2,5,6].includes(i)?'更新':i===3?'解冻':i===4?'注销':'注册',submitter:i===1?'李十':i%2?'ybhykxkj':'xuxiaolong',submitted:['2026-11-03 15:08:59','2026-10-29 17:16:19','2026-10-29 09:20:59','2026-10-28 09:50:39','2026-10-27 15:42:42','2026-10-22 17:38:45','2026-10-22 15:45:19','2026-10-20 16:00:30','2026-10-20 15:05:06'][i]})),
 agent:[{name:'李一',code:'xp9a507oq86i3k1wjx',organization:'李二家族企业集团',organizationCode:'91500100RGM16RFG9',type:'注册',submitter:'李二',submitted:'2026-09-01 16:59:51'}]
};
// Renewal applications share the existing approval queue and subject tabs.
for(const [kind,sourceIndex,expiry,days] of [['personal',0,'2026-11-12',180],['enterprise',0,'2026-11-01',90]]){
 const subject=identityExamples[kind][sourceIndex];
 identityExamples[kind].push({...subject,type:'续期',submitted:'2026-11-06 09:30:00',renewal:{firstRenewal:kind==='agent'?'':'2026-05-16',expiry,days,reason:'申请延长主体身份有效期，继续办理相关业务。'}});
}
function identityRenewalDate(expiry,days,approvedAt){
 const day=approvedAt||new Date().toLocaleDateString('sv-SE',{timeZone:'Asia/Shanghai'});
 const base=expiry>day?expiry:day,date=new Date(base+'T00:00:00+08:00');
 date.setUTCDate(date.getUTCDate()+Number(days));
 return new Date(date.getTime()+8*3600000).toISOString().slice(0,10);
}
let identityQueue='pending',identityKind='personal',identityMenuOpen=true;
const identityViews={};
const identityPage=()=>`identity-${identityQueue}-${identityKind}`;
const identityReq=(module,element=module)=>req(`identity.review.${identityQueue}.${identityKind}.${module}`,`identity.review.${identityQueue}.${identityKind}.${element}`);
function identityView(){return identityViews[identityPage()] ||= {type:'注册',draft:{},filters:{},page:1,size:10};}
function identityOpen(queue='pending',kind='personal',type,initial=false){
 if(identityAudit)identityAuditClose();
 identityQueue=queue==='completed'?'completed':'pending';identityKind=identityKinds[kind]?kind:'personal';section='identity';$('#overlay').innerHTML='';document.querySelector('#audit')?.remove();
 const v=identityView();if(type&&identityTypesFor(identityKind).includes(type))v.type=type;if(!identityTypesFor(identityKind).includes(v.type))v.type='注册';
 const u=new URL(location.href);u.searchParams.set('system','identity');u.searchParams.set('view',identityQueue);u.searchParams.set('kind',identityKind);u.searchParams.set('auditType',v.type);if(!initial)u.searchParams.delete('review');history.replaceState(null,'',u);render();
}
function identityQueryFields(kind=identityKind,type=identityView().type,completed=identityQueue==='completed'){
 const base=identitySchemas[kind].fields,keys=kind==='agent'?['name','code','organization','organizationCode']:kind==='personal'?['name','code','phone']:['name','code'];
 const identifiers=base.filter(([key])=>keys.includes(key)),dates=[['dateFrom','提交开始日期',null,'date'],['dateTo','提交结束日期',null,'date']];
 let fields=type==='注册'?base:type==='更新'?[...identifiers,['submitter','提交人'],...dates]:type==='续期'?[...identifiers,['expiryStatus','到期状态',['未到期','已到期']],['renewalDays','申请续期时长（天）',null,'number'],...dates]:type==='解冻'?[...identifiers.filter(([key])=>key!=='phone'),['appealPhone','申诉联系电话'],...dates]:[...identifiers,['submitter','提交人'],...dates];
 return [...fields,...(completed?[['result','审核结果',['通过','驳回']]]:[])];
}
function identityQuery(reset=false){
 const v=identityView();if(reset){v.draft={};v.filters={};}else{
  const next=Object.fromEntries(Object.entries(v.draft).map(([k,value])=>[k,String(value).trim()]));
  if(next.dateFrom&&next.dateTo&&next.dateFrom>next.dateTo){toast('提交开始日期不能晚于结束日期');return;}
  if(next.renewalDays&&(!Number.isInteger(Number(next.renewalDays))||Number(next.renewalDays)<1||Number(next.renewalDays)>180)){toast('申请续期时长须为1–180天的整数');return;}
  const keys=new Set(identityQueryFields().map(([key])=>key));v.filters=Object.fromEntries(Object.entries(next).filter(([key])=>keys.has(key)));
 }v.page=1;identityRender();
}
function identityRecord(kind,index,completed=false){
 const source=identityExamples[kind][index];if(!source)return null;
 const record={...source,_index:index,...(completed?{result:index%3===1?'驳回':'通过',reviewedAt:source.type==='续期'?'2026-11-06 10:00:00':'2026-11-04 09:20:00'}:{}),...(identityDecisions[kind+'.'+index]||{})};
 if(record.renewal){const today=new Date().toLocaleDateString('sv-SE',{timeZone:'Asia/Shanghai'});record.expiryStatus=record.renewal.expiry<today?'已到期':'未到期';record.renewalDays=String(record.renewal.days);}
 if(record.type==='解冻')record.appealPhone=window.IdentityWorkflowData.unfreeze(kind,record).phone;
 return record;
}
function identityFilteredRecords(){
 const v=identityView(),completed=identityQueue==='completed',fields=identityQueryFields();
 return identityExamples[identityKind].map((_,i)=>identityRecord(identityKind,i,completed)).filter(r=>r.type===v.type&&(completed||!identityDecisions[identityKind+'.'+r._index])).filter(r=>Object.entries(v.filters).every(([key,value])=>{
  if(!value)return true;if(key==='dateFrom')return r.submitted.slice(0,10)>=value;if(key==='dateTo')return r.submitted.slice(0,10)<=value;
  return fields.find(f=>f[0]===key)?.[2]||key==='renewalDays'?String(r[key]||'')===value:String(r[key]||'').includes(value);
 }));
}
function identityRender(){
 const completed=identityQueue==='completed',title=completed?'我已审批':'待我审批',schema=identitySchemas[identityKind],v=identityView(),fields=identityQueryFields(),list=identityFilteredRecords();
 document.querySelector('header b').textContent='主体身份管理系统';
 $('#sidebar').innerHTML=`<button class="identity-menu nav" aria-expanded="${identityMenuOpen}" onclick="identityMenuOpen=!identityMenuOpen;identityRender()"><span>▣</span>审核管理<em>${identityMenuOpen?'⌄':'›'}</em></button>${identityMenuOpen?['pending','completed'].map(q=>`<button class="identity-menu nav identity-sub ${identityQueue===q?'active':''}" onclick="identityOpen('${q}',identityKind)">${q==='pending'?'待我审批':'我已审批'}</button>`).join(''):''}<button class="identity-menu nav identity-return" onclick="section='launch';history.replaceState(null,'','?system=management');render()"><span>⇤</span>返回快捷入口</button>`;
 const pages=Math.max(1,Math.ceil(list.length/v.size));v.page=Math.min(v.page,pages);
 const columns=[...schema.columns,...(completed?[['result','审核结果']]:[])];
 $('#main').innerHTML=`<div class="systemtabs"><span onclick="section='launch';history.replaceState(null,'','?system=management');render()">首页</span><span class="selected">● ${title}</span></div><div class="identity-page" data-req-page="${identityPage()}" data-req-surface="${identityPage().replaceAll('-','.')+'.'+identityTypeCode(v.type)}" data-req-title="${title} · ${identityKinds[identityKind]} · ${v.type}"><section class="identity-navigation"><div class="identity-tabs" role="tablist" aria-label="主体类型" ${identityReq('list','tabs')}>${Object.entries(identityKinds).map(([k,n])=>`<button role="tab" aria-selected="${k===identityKind}" class="${k===identityKind?'active':''}" onclick="identityOpen(identityQueue,'${k}')" ${identityReq('list','tab.'+k)}>${n}</button>`).join('')}</div>${identityTypeNavigation(identityKind)}</section><form class="identity-filters" onsubmit="event.preventDefault();identityQuery()" ${identityReq('query','query.'+identityTypeCode(v.type))}><div class="identity-query-fields">${fields.map(([k,n,options,inputType])=>`<label ${identityReq('query','query.'+identityTypeCode(v.type)+'.field.'+k)}><span>${n}</span>${options?`<select name="${k}" aria-label="${n}" onchange="identityView().draft[this.name]=this.value"><option value="">全部</option>${options.map(x=>`<option ${v.draft[k]===x?'selected':''}>${esc(x)}</option>`).join('')}</select>`:`<input name="${k}" aria-label="${n}" type="${inputType||'text'}" ${inputType==='number'?'min="1" max="180" step="1"':'maxlength="100"'} placeholder="请输入" value="${esc(v.draft[k]||'')}" oninput="identityView().draft[this.name]=this.value">`}</label>`).join('')}</div><div class="identity-query-actions"><button class="btn" type="button" onclick="identityQuery(true)" ${identityReq('query','query.reset')}>重置</button><button class="btn primary" type="submit" ${identityReq('query','query.submit')}>查询</button></div></form><section class="identity-results" ${identityReq('list')} aria-label="${identityKinds[identityKind]}${v.type}${title}列表"><div class="identity-table-tools"><h2>${v.type}申请</h2><button type="button" aria-label="刷新列表" title="刷新列表" onclick="identityRender()" ${identityReq('list','refresh')}>↻</button></div><div class="identity-table-scroll"><table><thead><tr>${columns.map(([k,n])=>`<th>${n}</th>`).join('')}<th>操作</th></tr></thead><tbody>${list.slice((v.page-1)*v.size,v.page*v.size).map(r=>`<tr>${columns.map(([k])=>`<td title="${esc(r[k]||'—')}">${k==='type'||k==='result'?`<span class="identity-badge ${k==='result'?(r[k]==='通过'?'green':'red'):r[k]==='更新'?'orange':''}">${esc(r[k])}</span>`:esc(r[k]||'—')}</td>`).join('')}<td><button type="button" class="link" onclick="identityAuditOpen(${r._index})" ${identityReq('list',completed?'record.view':'approval.open')}>${completed?'查看':'审批'}</button></td></tr>`).join('')||`<tr><td colspan="${columns.length+1}" class="empty">暂无匹配记录</td></tr>`}</tbody></table></div><div class="identity-pagination" ${identityReq('list','pagination')}><span>共 ${list.length} 条</span><select aria-label="每页条数" onchange="identityView().size=Number(this.value);identityView().page=1;identityRender()">${[10,20,50].map(n=>`<option value="${n}" ${n===v.size?'selected':''}>${n}条/页</option>`).join('')}</select><button ${v.page===1?'disabled':''} aria-label="上一页" onclick="identityView().page--;identityRender()">‹</button><b>${v.page}</b><button ${v.page===pages?'disabled':''} aria-label="下一页" onclick="identityView().page++;identityRender()">›</button><label>前往 <input type="number" aria-label="跳转页码" min="1" max="${pages}" value="${v.page}" onchange="identityView().page=Math.max(1,Math.min(${pages},Math.floor(Number(this.value)||1)));identityRender()"> 页</label></div></section></div>`;
 window.dispatchEvent(new CustomEvent('ai-prototype:context-changed'));
}
const identityPreviousRender=render;
render=function(){if(section==='identity'){identityRender();return;}identityPreviousRender();};
document.addEventListener('click',event=>{if(event.target.closest('.cards > .card[data-req-id="system.2"]')){event.preventDefault();event.stopImmediatePropagation();selectSystem(2);identityOpen();}},true);
if(new URLSearchParams(location.search).get('system')==='identity'){const p=new URLSearchParams(location.search);identityOpen(p.get('view'),p.get('kind'),p.get('auditType'),true);}

const identityAuditModule=(name,element=name)=>req(`identity.review.${identityAudit.kind}.audit.${name}`,`identity.review.${identityAudit.kind}.audit.${element}`);
function identityAuditOpen(index){
 const row=identityRecord(identityKind,index,identityQueue==='completed');if(!row||!identityTypesFor(identityKind).includes(row.type))return;
 identityAudit={kind:identityKind,index,row,type:row.type,readOnly:identityQueue==='completed',drafts:{},material:null,confirm:false,error:''};
 ['header','#sidebar','#main'].forEach(selector=>{const element=document.querySelector(selector);if(element)element.inert=true;});
 identityAuditRender();$('#overlay [role="dialog"]').focus();
}
function identityAuditDraft(){return identityAudit.drafts[identityAudit.type] ||= {result:'',opinion:''};}
function identityAuditSwitch(type){if(!identityAudit||!identityTypesFor(identityAudit.kind).includes(type))return;identityAudit.type=type;identityAudit.confirm=false;identityAudit.error='';identityAudit.material=null;identityAuditRender();}
function identityAuditClose(){['header','#sidebar','#main'].forEach(selector=>{const element=document.querySelector(selector);if(element)element.inert=false;});identityAudit=null;$('#overlay').innerHTML='';window.dispatchEvent(new CustomEvent('ai-prototype:context-changed'));document.querySelector('.identity-results .link')?.focus();}
function identityAuditRender(){
 const a=identityAudit;if(!a)return;const scrollTop=document.querySelector('.identity-audit-information')?.scrollTop||0;const sideScrollTop=document.querySelector('.identity-audit-side')?.scrollTop||0;const personal=a.kind==='personal',draft=identityAuditDraft(),preview=a.type!==a.row.type;
 const context={续期:['主体身份有效期续期审核','核对当前有效期和申请续期时长，确认续期后到期时间。','审核通过后延长主体身份有效期'],注册:['新主体身份注册审核','核对申请人的认证信息与证件材料，确认身份信息真实、完整、一致。','未注册 → 审核通过后完成身份注册'],更新:['主体认证信息更新审核','重点核对变更字段及证明材料，确认申请更新的信息有据可查。','可用 → 审核通过后更新认证信息'],解冻:['主体身份解冻审核','核对解冻申请说明及整改材料，确认恢复身份使用的依据。','冻结 → 审核通过后恢复可用'],注销:['主体身份注销审核','核对注销意愿、申请说明与相关材料，审慎确认注销申请。','可用 → 审核通过后注销']}[a.type];
 const groups=window.IdentityCertification.groups(a.kind,a.type==='续期'?{...a.row,expiresAt:a.row.renewal?.expiry}:a.row),surface=`identity.review.${a.kind}.audit.${a.type==='注册'?'register':a.type==='更新'?'update':a.type==='续期'?'renew':a.type==='解冻'?'unfreeze':'cancel'}`;
 $('#overlay').innerHTML=`<div class="identity-audit-veil"><section class="identity-audit-dialog" role="dialog" aria-modal="true" tabindex="-1" aria-labelledby="identity-audit-title" data-req-page="${identityPage()}" data-req-surface="${surface}" data-req-layer="dialog" data-req-title="${identityKinds[a.kind]}${a.type}审核"><div class="identity-audit-header" ${identityAuditModule('context')}><div><span class="identity-audit-eyebrow">主体身份审核 · ${identityKinds[a.kind]}</span><h1 id="identity-audit-title">${a.type}审核 <span class="identity-audit-state">${a.readOnly?(a.row.result||'通过'):'待我审批'}</span></h1></div><button class="identity-audit-close" aria-label="关闭审核弹窗" onclick="identityAuditClose()">×</button></div><div class="identity-audit-scenarios" ${identityAuditModule('context','type.switch')}><span>审核类型</span><div role="tablist" aria-label="切换审核类型">${identityTypesFor(a.kind).map(t=>`<button role="tab" aria-selected="${a.type===t}" class="${a.type===t?'active':''}" onclick="identityAuditSwitch('${t}')">${t}</button>`).join('')}</div></div><p class="identity-audit-demo-hint">此处多个审核类型弹窗仅作原型展示，真实审核流每次只有一个审核类型。</p><div class="identity-audit-layout"><div class="identity-audit-information"><section class="identity-audit-focus" ${identityAuditModule('context','subject')}><span class="identity-audit-focus-icon">${personal?'♙':'▥'}</span><div><h2>${esc(a.row.name)}</h2><p>${personal?'证件号码':a.kind==='agent'?'经办人标识':'统一社会信用代码'}：${esc(a.row.code)}</p><p>提交人：${esc(a.row.submitter)} <span>提交时间：${esc(a.row.submitted)}</span></p></div><div class="identity-audit-ref"><span>申请编号</span><strong>CQ-${personal?'P':'E'}-20261104-${String(a.index+1).padStart(3,'0')}</strong></div></section><section class="identity-audit-section" ${identityAuditModule('request','request.'+identityTypeCode(a.type))}><div class="identity-audit-section-title"><h2>本次${a.type}申请</h2><span>${context[0]}</span></div><div class="identity-audit-request">${a.type==='更新'?`<table class="identity-audit-diff"><thead><tr><th>变更字段</th><th>变更前</th><th>本次申请值</th></tr></thead><tbody><tr><td>${personal?'证件有效期':a.kind==='agent'?'所属组织名称':'经营期限'}</td><td>${personal?'2019-07-02 至 2029-07-02':a.kind==='agent'?esc(a.row.organization)+'（原名称）':'2024-10-30 至 2034-10-29'}</td><td><strong>${personal?'2019-07-02 至 2035-07-02':a.kind==='agent'?esc(a.row.organization):'2024-10-30 至 长期'}</strong></td></tr></tbody></table>`:a.type==='注册'?'<dl><dt>申请说明</dt><dd>申请注册主体身份，已提交认证信息及相关证明材料。</dd></dl>':a.type==='续期'?identityRenewalFields():a.type==='解冻'?identityUnfreezeFields():`<dl><dt>${a.type}原因</dt><dd>${{解冻:'相关问题已完成整改，申请解除冻结并恢复身份使用。',注销:'申请终止该主体身份使用，请审核注销信息与证明材料。'}[a.type]}</dd></dl>`}</div></section><section class="identity-audit-section" ${identityAuditModule('info')}><div class="identity-audit-section-title"><h2>基本信息</h2></div>${groups.map(group=>group.permissions?identityAgentPermissionBlock(group):group.signature?identityAgentSignatureBlock(group):group.materials?`<div class="identity-audit-info-group" ${identityAuditModule('materials','materials.'+groups.indexOf(group))}><h3>${group.title}</h3><div class="identity-audit-files">${group.rows.map(([label,file])=>`<button onclick="identityAuditMaterial('${file}')"><span class="identity-audit-file-icon">${file.endsWith('.csr')?'CSR':file.endsWith('.pdf')?'PDF':'IMG'}</span><span><strong>${esc(label)}</strong><small>${file}</small></span><em>查看</em></button>`).join('')}</div></div>`:`<div class="identity-audit-info-group"><h3>${group.title}</h3><dl class="identity-audit-fields">${group.rows.map(([name,value,wide])=>`<div class="${wide?'wide':''}"><dt>${window.IdentityCertification.isRequired(a.kind,name)?'<em class="identity-required" aria-label="必填">*</em>':''}${esc(name)}</dt><dd>${esc(name==='申请状态'?(a.readOnly?(a.row.result||'通过'):'待审核'):value)}</dd></div>`).join('')}</dl></div>`).join('')}${a.material?`<div class="identity-audit-material-note" role="status"><strong>材料查看 · ${esc(a.material)}</strong><button class="link" onclick="identityAudit.material=null;identityAuditRender()">收起</button></div>`:''}</section></div><div class="identity-audit-side"><aside class="identity-audit-decision" ${identityAuditModule('decision')}><div class="identity-audit-decision-heading"><span>审核工作区</span><h2>${a.readOnly?'审核结果':'请完成'+a.type+'审核'}</h2></div>${a.readOnly?`<div class="identity-audit-read-result"><span class="identity-badge ${(a.row.result||'通过')==='通过'?'green':'red'}">${esc(a.row.result||'通过')}</span><dl><dt>审核人</dt><dd>当前运营人员</dd><dt>审核时间</dt><dd>${esc(a.row.reviewedAt||(a.type==='续期'?'2026-11-06 10:00:00':'2026-11-04 09:20:00'))}</dd><dt>审核意见</dt><dd>${esc(a.row.opinion||((a.row.result||'通过')==='通过'?'认证信息与证明材料一致，审核通过。':'申请资料不完整，请补充有效证明材料。'))}</dd></dl></div>`:`<form id="identity-audit-form" onsubmit="event.preventDefault();identityAuditConfirm()"><fieldset><legend>审核结果 <em>*</em></legend><label class="identity-audit-choice ${draft.result==='通过'?'selected':''}"><input type="radio" name="audit-result" value="通过" ${draft.result==='通过'?'checked':''} onchange="identityAuditDraft().result=this.value;identityAudit.confirm=false;identityAuditRender()">通过</label><label class="identity-audit-choice ${draft.result==='驳回'?'selected':''}"><input type="radio" name="audit-result" value="驳回" ${draft.result==='驳回'?'checked':''} onchange="identityAuditDraft().result=this.value;identityAudit.confirm=false;identityAuditRender()">驳回</label></fieldset><label class="identity-audit-opinion">审核意见 ${draft.result==='驳回'?'<em>*</em>':'<span>（选填）</span>'}<textarea aria-label="审核意见" maxlength="500" placeholder="${draft.result==='驳回'?'请填写驳回原因，便于申请人补充或修改资料':'请输入审核意见'}" oninput="identityAuditDraft().opinion=this.value;identityAudit.confirm=false">${esc(draft.opinion)}</textarea></label><p class="identity-audit-error" role="alert">${esc(a.error)}</p><div class="identity-audit-submit"><button type="submit" class="btn primary" ${preview?'disabled':''}>提交审核</button></div></form>`}</aside>${identityAuditFlowPanel()}</div></div></section></div>${a.confirm?identityAuditConfirmation():''}`;
 const information=document.querySelector('.identity-audit-information');if(information)information.scrollTop=scrollTop;
 const side=document.querySelector('.identity-audit-side');if(side)side.scrollTop=sideScrollTop;
 const mainDialog=document.querySelector('.identity-audit-dialog');if(mainDialog)mainDialog.inert=!!a.confirm;
 if(a.confirm)document.querySelector('.identity-audit-confirm-dialog [data-confirm-cancel]')?.focus();
 window.dispatchEvent(new CustomEvent('ai-prototype:context-changed'));
}
function identityAuditMaterial(file){identityAudit.material=file;identityAuditRender();document.querySelector('.identity-audit-material-note')?.scrollIntoView({block:'center'});}
function identityAuditConfirm(){const a=identityAudit,d=identityAuditDraft();a.error=!d.result?'请选择审核结果。':d.result==='驳回'&&!d.opinion.trim()?'请填写驳回原因。':d.opinion.trim().length>500?'审核意见最多 500 字。':'';if(!a.error&&a.type==='续期'){const r=a.row.renewal;if(!r||!/^\d{4}-\d{2}-\d{2}$/.test(r.expiry)||!Number.isFinite(Date.parse(r.expiry))||!Number.isInteger(r.days)||r.days<1||r.days>180)a.error='请核对当前到期时间和续期时长，单次续期必须为1–180天的整数。';}if(!a.error&&a.type==='解冻'){const data=window.IdentityWorkflowData.unfreeze(a.kind,a.row);if(!data.freezeReason||!data.reason||!/^1[3-9]\d{9}$/.test(data.phone))a.error='冻结原因、申诉说明和有效的申诉联系电话均为必填，请核对关联的冻结记录与解冻申请。';}a.confirm=!a.error;identityAuditRender();}
function identityAuditSubmit(){const a=identityAudit,d=identityAuditDraft();if(!a.confirm||a.readOnly||!identityTypesFor(a.kind).includes(a.type)||identityDecisions[a.kind+'.'+a.index]||a.type!==a.row.type||!d.result||(d.result==='驳回'&&!d.opinion.trim()))return;const reviewedAt=new Date().toLocaleString('sv-SE',{timeZone:'Asia/Shanghai'});identityDecisions[a.kind+'.'+a.index]={type:a.type,result:d.result,opinion:d.opinion.trim(),reviewedAt,...(a.type==='续期'?{renewal:{...a.row.renewal,effectiveExpiry:d.result==='通过'?identityRenewalDate(a.row.renewal.expiry,a.row.renewal.days,reviewedAt.slice(0,10)):a.row.renewal.expiry}}:{})};identityAuditClose();identityRender();toast('审核结果已记录');}
document.addEventListener('keydown',event=>{if(!identityAudit)return;if(event.key==='Escape'){event.preventDefault();if(identityAudit.confirm)identityAuditCancelConfirmation();else identityAuditClose();return;}if(event.key==='Tab'){const dialog=document.querySelector('.identity-audit-confirm-dialog')||document.querySelector('.identity-audit-dialog'),controls=[...dialog.querySelectorAll('button,input,select,textarea,[tabindex="0"]')].filter(x=>!x.disabled),first=controls[0],last=controls.at(-1);if(event.shiftKey&&(document.activeElement===first||document.activeElement===dialog)){event.preventDefault();last?.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first?.focus();}}});
const identityAuditParams=new URLSearchParams(location.search);
if(section==='identity'&&identityAuditParams.get('review')==='1'){
 const type=identityView().type,index=identityExamples[identityKind].findIndex(r=>r.type===type);
 if(index>=0)identityAuditOpen(index);
}

function identityPendingCounts(kind){return identityExamples[kind].reduce((counts,r,index)=>{if(identityTypesFor(kind).includes(r.type)&&!identityDecisions[kind+'.'+index])counts[r.type]++;return counts;},Object.fromEntries(identityTypesFor(kind).map(type=>[type,0])));}
function identityTypeNavigation(kind){const counts=identityPendingCounts(kind),v=identityView();return `<div class="identity-type-navigation" role="tablist" aria-label="审核类型" ${req('identity.review.'+kind+'.counts','identity.review.'+kind+'.types')}>${identityTypesFor(kind).map(type=>`<button type="button" role="tab" aria-selected="${v.type===type}" class="identity-type-tab ${v.type===type?'active':''}" onclick="identityFilterType('${type}')" ${req('identity.review.'+kind+'.counts','identity.review.'+kind+'.type.'+identityTypeCode(type))}><span>${type}</span>${identityQueue==='pending'?`<b>${counts[type]}</b>`:''}</button>`).join('')}</div>`;}
function identityFilterType(type){if(!identityTypesFor(identityKind).includes(type))return;const v=identityView();if(v.type===type)return;v.type=type;v.draft={};v.filters={};v.page=1;const u=new URL(location.href);u.searchParams.set('auditType',type);u.searchParams.delete('review');history.replaceState(null,'',u);identityRender();}
function identityAuditFlowRecords(){
 const a=identityAudit;if(!a||!identityTypesFor(a.kind).includes(a.type))return [];
 return identityExamples[a.kind].map((r,index)=>({r,index})).filter(({r})=>r.code===a.row.code&&r.type===a.type).map(({r,index})=>{
  const decision=identityDecisions[a.kind+'.'+index],current=index===a.index,completed=!!decision||(current&&a.readOnly);
  return {...r,...(completed?(decision||a.row):{}),completed};
 }).sort((a,b)=>a.submitted.localeCompare(b.submitted));
}
function identityAuditFlowPanel(){
 const a=identityAudit,records=identityAuditFlowRecords();
 return `<section class="identity-audit-section identity-flow-section" ${identityAuditModule('flow')}><div class="identity-audit-section-title"><h2>历史审核记录</h2><span class="identity-flow-type">${identityKinds[a.kind]}</span></div><div class="identity-flow-body">${records.map(r=>`<ol class="identity-flow" aria-label="${esc(r.name)}${a.type}历史审核记录"><li class="done"><span class="identity-flow-marker">✓</span><div class="identity-flow-content"><div class="identity-flow-line"><strong>提交${a.type}申请</strong><time>${esc(r.submitted)}</time></div><p>${esc(r.submitter)}</p></div></li><li class="${r.completed?(r.result==='驳回'?'rejected':'done'):'current'}"><span class="identity-flow-marker">${r.completed?(r.result==='驳回'?'×':'✓'):'2'}</span><div class="identity-flow-content"><div class="identity-flow-line"><strong>运营审核</strong><span class="identity-flow-status ${r.completed?(r.result==='驳回'?'rejected':'done'):'current'}">${r.completed?'审核'+r.result:'待审核'}</span></div><p>${r.completed?'当前运营人员':'运营审核员'}${r.completed?`<time>${esc(r.reviewedAt)}</time>`:''}</p>${r.completed?`<div class="identity-flow-opinion">${esc(r.opinion||(r.result==='驳回'?'申请资料不完整，请补充有效证明材料。':'审核通过。'))}</div>`:''}</div></li><li class="${r.completed?'done':'upcoming'}"><span class="identity-flow-marker">${r.completed?'✓':'3'}</span><div class="identity-flow-content"><div class="identity-flow-line"><strong>审核完成</strong>${r.completed?`<time>${esc(r.reviewedAt)}</time>`:''}</div>${r.completed?`<p>${r.result==='驳回'?'申请已驳回':r.type==='续期'?'续期后到期时间：'+(r.renewal?.effectiveExpiry||identityRenewalDate(r.renewal.expiry,r.renewal.days,r.reviewedAt.slice(0,10))):'申请已通过'}</p>`:''}</div></li></ol>`).join('')||'<div class="identity-flow-empty">暂无该类型审核申请</div>'}</div></section>`;
}
function identityUnfreezeFields(){const a=identityAudit,data=window.IdentityWorkflowData.unfreeze(a.kind,a.row);return `<dl class="identity-unfreeze-fields"><dt><em class="identity-required">*</em>冻结原因</dt><dd>${esc(data.freezeReason||'未提供')}</dd><dt><em class="identity-required">*</em>申诉说明</dt><dd>${esc(data.reason||'未提供')}</dd><dt><em class="identity-required">*</em>申诉联系电话</dt><dd>${esc(data.phone||'未提供')}</dd></dl>`;}
function identityAgentPermissionBlock(group){return `<div class="identity-audit-info-group identity-agent-permissions"><h3><em class="identity-required">*</em>${group.title}</h3><table><thead><tr><th>权限名称</th><th>数据范围</th></tr></thead><tbody>${group.rows.map(([permission,scope])=>`<tr><td>${esc(permission)}</td><td>${esc(scope)}</td></tr>`).join('')}</tbody></table></div>`;}
function identityAgentSignatureBlock(group){return `<div class="identity-audit-info-group identity-agent-signature"><h3>${group.title}</h3><dl>${group.rows.map(([name,value])=>`<div><dt><em class="identity-required">*</em>${name}</dt><dd>${esc(value)}</dd></div>`).join('')}</dl></div>`;}

function identityAuditConfirmation(){const a=identityAudit,draft=identityAuditDraft();return `<div class="identity-audit-confirm-veil"><section class="identity-audit-confirm-dialog" role="dialog" aria-modal="true" aria-labelledby="identity-confirm-title" tabindex="-1" data-req-page="${identityPage()}" data-req-layer="dialog" data-req-surface="identity.review.${a.kind}.audit.confirm" data-req-title="提交审核确认" ${identityAuditModule('decision','decision.confirm')}><div class="identity-confirm-heading"><span class="identity-confirm-icon">!</span><h2 id="identity-confirm-title">确认提交审核？</h2><button type="button" aria-label="关闭审核确认" onclick="identityAuditCancelConfirmation()">×</button></div><div class="identity-confirm-body"><p>确认<strong>${esc(draft.result)}</strong>以下${esc(a.type)}申请？</p><dl><div><dt>审核对象</dt><dd>${esc(a.row.name)}</dd></div><div><dt>主体类型</dt><dd>${identityKinds[a.kind]}</dd></div><div><dt>审核类型</dt><dd>${esc(a.type)}</dd></div><div><dt>审核结果</dt><dd><span class="identity-badge ${draft.result==='通过'?'green':'red'}">${esc(draft.result)}</span></dd></div>${a.type==='续期'?`<div><dt>当前到期时间</dt><dd>${esc(a.row.renewal?.expiry||'未提供')}</dd></div><div><dt>申请续期时长</dt><dd>${esc(String(a.row.renewal?.days||''))} 天</dd></div><div><dt>${draft.result==='通过'?'通过后到期时间':'驳回后到期时间'}</dt><dd>${esc(draft.result==='通过'?identityRenewalDate(a.row.renewal.expiry,a.row.renewal.days):a.row.renewal.expiry)}</dd></div>`:''}${draft.opinion.trim()?`<div><dt>审核意见</dt><dd>${esc(draft.opinion.trim())}</dd></div>`:''}</dl></div><div class="identity-confirm-footer"><button type="button" class="btn" data-confirm-cancel onclick="identityAuditCancelConfirmation()">取消</button><button type="button" class="btn ${draft.result==='驳回'?'identity-audit-reject':'primary'}" onclick="identityAuditSubmit()">确认提交</button></div></section></div>`;}
function identityAuditCancelConfirmation(){if(!identityAudit)return;identityAudit.confirm=false;identityAuditRender();document.querySelector('#identity-audit-form button[type="submit"]')?.focus();}

function identityRenewalFields(){
 const a=identityAudit,record=identityAuditFlowRecords().at(-1),r=record?.renewal;if(!r)return '<div class="identity-flow-empty">暂无续期申请</div>';const result=record.result,completed=record.completed;
 const expiry=completed?(r.effectiveExpiry||(result==='驳回'?r.expiry:identityRenewalDate(r.expiry,r.days,record.reviewedAt.slice(0,10)))):identityRenewalDate(r.expiry,r.days);
 return `<dl class="identity-audit-fields identity-renewal-fields" ${identityAuditModule('request','renewal.fields')}><div><dt>首次续期时间</dt><dd>${esc(r.firstRenewal||'暂无（首次申请）')}</dd></div><div><dt>当前到期时间</dt><dd>${esc(r.expiry)}</dd></div><div><dt>申请续期时长</dt><dd>${esc(String(r.days))} 天</dd></div><div><dt>${completed?'审核后到期时间':'预计续期后到期时间'}</dt><dd><strong>${esc(expiry)}</strong></dd></div><div class="wide"><dt>申请说明</dt><dd>${esc(r.reason||'—')}</dd></div></dl>`;
}
